const items = $input.all();

console.log('\n========== DEBUG: ZUORDNUNG PROBLEM ==========\n');
console.log(`Total items: ${items.length}`);

let kandidatenCount = 0;
let fachgeschaefteCount = 0;
let kandidatenMitAdresse = 0;
let fachgeschaefteMitAdresse = 0;
let kandidatenMitDistanz = 0;

for (const item of items) {
  const data = item.json;

  // Ist es ein Kandidat?
  if (data.property_geburtsdatum) {
    kandidatenCount++;
    console.log(`\n--- KANDIDAT ${kandidatenCount}: ${data.property_name} ---`);
    console.log(`  Wohnadresse: ${data.property_wohnadresse || 'LEER'}`);
    console.log(`  Gewünschte Distanz: ${data.property_gewunschte_distanz || 'NICHT GESETZT'}`);

    if (data.property_wohnadresse && data.property_wohnadresse.trim() !== '') {
      kandidatenMitAdresse++;
    }

    if (data.property_gewunschte_distanz) {
      kandidatenMitDistanz++;
    }
  }
  // Ist es ein Fachgeschäft?
  else if (data.property_adresse) {
    fachgeschaefteCount++;
    console.log(`\n--- FACHGESCHÄFT ${fachgeschaefteCount}: ${data.property_name} ---`);
    console.log(`  Adresse: ${data.property_adresse || 'LEER'}`);

    if (data.property_adresse && data.property_adresse.trim() !== '') {
      fachgeschaefteMitAdresse++;
    }
  }
}

console.log('\n========== ZUSAMMENFASSUNG ==========');
console.log(`Total Kandidaten: ${kandidatenCount}`);
console.log(`Kandidaten mit Adresse: ${kandidatenMitAdresse}`);
console.log(`Kandidaten mit Distanz-Einstellung: ${kandidatenMitDistanz}`);
console.log(`Total Fachgeschäfte: ${fachgeschaefteCount}`);
console.log(`Fachgeschäfte mit Adresse: ${fachgeschaefteMitAdresse}`);

console.log('\n========== PROBLEME ==========');
if (kandidatenMitAdresse === 0) {
  console.log('❌ PROBLEM: Keine Kandidaten haben Adressen!');
}
if (fachgeschaefteMitAdresse === 0) {
  console.log('❌ PROBLEM: Keine Fachgeschäfte haben Adressen!');
}
if (kandidatenMitDistanz === 0) {
  console.log('⚠️  WARNUNG: Keine Kandidaten haben Distanz-Einstellung (wird 50km Default verwendet)');
}

return [{
  json: {
    kandidaten_total: kandidatenCount,
    kandidaten_mit_adresse: kandidatenMitAdresse,
    kandidaten_mit_distanz: kandidatenMitDistanz,
    fachgeschaefte_total: fachgeschaefteCount,
    fachgeschaefte_mit_adresse: fachgeschaefteMitAdresse
  }
}];
